(31, 3, 'Yearly reminder', '<!doctype html>\n<html>\n  <head>\n    <meta charset=\"utf-8\">\n    <meta http-equiv=\"x-ua-compatible\" content=\"ie=edge\">\n    <title></title>\n    <meta name=\"description\" content=\"\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    \n    \n      <style type=\"text/css\">\n        a { color: #0000ee; text-decoration: underline; } a:hover { color: #0000ee; text-decoration: underline; }\n.u-row {\n  display: flex;\n  flex-wrap: nowrap;\n  margin-left: 0;\n  margin-right: 0;\n}\n\n.u-row .u-col {\n  position: relative;\n  width: 100%;\n  padding-right: 0;\n  padding-left: 0;\n}\n\n\n.u-row .u-col.u-col-100 {\n  flex: 0 0 100%;\n  max-width: 100%;\n}\n\n\n@media (max-width: 767px) {\n  .u-row:not(.no-stack) {\n    flex-wrap: wrap;\n  }\n\n  .u-row:not(.no-stack) .u-col {\n    flex: 0 0 100% !important;\n    max-width: 100% !important;\n  }\n}\n\nbody,html{padding:0;margin:0}html{box-sizing:border-box}*,:after,:before{box-sizing:inherit}html{font-size:14px;-ms-overflow-style:scrollbar;-webkit-tap-highlight-color:rgba(0,0,0,0)}body{font-family:Arial,Helvetica,sans-serif;font-size:1rem;line-height:1.5;color:#373a3c;background-color:#fff}p{margin:0}.error-field{-webkit-animation-name:shake;animation-name:shake;-webkit-animation-duration:1s;animation-duration:1s;-webkit-animation-fill-mode:both;animation-fill-mode:both}.error-field input,.error-field textarea{border-color:#a94442!important;color:#a94442!important}.field-error{padding:5px 10px;font-size:14px;font-weight:700;position:absolute;top:-20px;right:10px}.field-error:after{top:100%;left:50%;border:solid transparent;content:\" \";height:0;width:0;position:absolute;pointer-events:none;border-color:rgba(136,183,213,0);border-top-color:#ebcccc;border-width:5px;margin-left:-5px}.spinner{margin:0 auto;width:70px;text-align:center}.spinner>div{width:12px;height:12px;background-color:hsla(0,0%,100%,.5);margin:0 2px;border-radius:100%;display:inline-block;